        StringTokenizer tk = new StringTokenizer(br.readLine());
        int cap = Integer.parseInt(tk.nextToken());
        int q = Integer.parseInt(tk.nextToken());
        ArrayStack st = new ArrayStack(cap);
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < q; k++) {
