                sb.append(st.push(x) ? "ok" : "overflow").append('\n');
            } else if (op.equals("pop")) {
                sb.append(st.isEmpty() ? "underflow" : String.valueOf(st.pop())).append('\n');
            } else if (op.equals("top")) {
                sb.append(st.isEmpty() ? "empty" : String.valueOf(st.top())).append('\n');
            } else if (op.equals("size")) {
                sb.append(st.size()).append('\n');
            } else {
                sb.append(st.isEmpty() ? "true" : "false").append('\n');
            }
        }
        System.out.print(sb);
