def gen(rng):
    def fmt(cap, ops):
        return f"{cap} {len(ops)}\n" + '\n'.join(ops)
    def rand_ops(q, vmax, weights):
        ops = []
        for _ in range(q):
            o = rng.choices(['push', 'pop', 'top', 'size', 'isempty'], weights)[0]
            ops.append(f"push {rng.randint(-vmax, vmax)}" if o == 'push' else o)
        return ops
    M = 10**9
    tests = [fmt(1, ['pop']), fmt(1, ['push 5', 'push 6', 'top', 'size', 'pop', 'pop', 'isempty']),
             fmt(3, ['isempty', 'top', 'size', 'push -4', 'isempty', 'top']),
             fmt(2, ['push 5', 'push 7', 'push 9', 'top', 'pop', 'size', 'pop', 'pop', 'isempty']),
             fmt(2, [f'push {M}', f'push {-M}', 'pop', 'pop', 'top'])]
    for cap in (1, 2, 3, 5, 8):
        for _ in range(2):
            tests.append(fmt(cap, rand_ops(rng.randint(5, 30), 50, [5, 4, 2, 2, 2])))
    tests.append(fmt(10**5, rand_ops(10**5, M, [5, 3, 2, 1, 1])))
    tests.append(fmt(50000, ['push %d' % rng.randint(-M, M) for _ in range(60000)] + ['pop'] * 40000))
    tests.append(fmt(1000, rand_ops(10**5, M, [5, 5, 1, 1, 1])))
    return tests
